'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {afterDays} from '@/lib/rates';
import {downloadReport,reportMoney,type ReportCell} from '@/lib/report-export';
import {serviceUsageLabel,serviceComponents,type ClosedServiceReport,type ServiceEntry} from '@/lib/service-days';
import {PendingForwardList,pendingForwardRows,pendingForwardHeaders} from '@/components/service-forward';
import {taxBuckets,type ForwardEntry} from '@/lib/service-forward';
import {ServiceTotalsBreakdown} from '@/components/service-totals';

const forwardHeaders=['Posting service date','Original service start','Original service end (exclusive)','Guest','Reservation','Adjustment reference','Accommodation correction USD','Total tax correction USD','Property fee correction (category unallocated) USD','OTA fee correction USD','Other revenue correction USD','Combined tax correction USD','City tax correction USD','State tax correction USD','Lodging tax correction USD','Uncategorized tax correction USD','Revenue correction USD','Total correction USD','Reason'];
export function forwardReportRow(e:ForwardEntry):ReportCell[]{return [e.service_date,e.details.original_service_start,e.details.original_service_end,e.details.guest_name,e.reservation_id,e.adjustment_id,...serviceComponents.map(([k])=>reportMoney(e[k])),...taxBuckets.map(([k])=>reportMoney(e.tax_buckets[k])),reportMoney(e.accommodation_minor+e.hotel_fees_minor+e.other_revenue_minor),reportMoney(e.total_minor),e.details.reason]}
const headers=['Service night','Guest','Reservation','Accommodation USD','City tax allocated USD','State tax allocated USD','Lodging tax allocated USD','Combined tax allocated USD','Uncategorized tax USD','Resort fee allocated USD','Technology fee allocated USD','Cleaning fee allocated USD','Uncategorized fees USD','OTA fees USD','Other revenue USD','Revenue subtotal USD','Total allocation USD','Allocation basis','Service use','Occupied overnight'];
function reportEntry(entry:ServiceEntry):ReportCell[]{
 const taxes=entry.details.taxes??[],fees=entry.details.fees??[];
 const tax=(code:string)=>taxes.filter(t=>t.code===code).reduce((sum,t)=>sum+t.amount_minor,0);
 const fee=(code:string)=>fees.filter(f=>f.code===code).reduce((sum,f)=>sum+f.amount_minor,0);
 const namedTaxes=['city','state','lodging','legacy'].map(tax),namedFees=['resort','technology','cleaning'].map(fee);
 return [entry.service_date,entry.details.guest_name??'',entry.reservation_id,...[entry.accommodation_minor,...namedTaxes,entry.taxes_minor-namedTaxes.reduce((a,b)=>a+b,0),...namedFees,entry.hotel_fees_minor-namedFees.reduce((a,b)=>a+b,0),entry.ota_fees_minor,entry.other_revenue_minor,entry.accommodation_minor+entry.hotel_fees_minor+entry.other_revenue_minor,entry.total_minor].map(reportMoney),entry.details.tax_allocation==='manager_aggregate'?'Manager aggregate allocation':entry.details.tax_allocation==='legacy_aggregate'?'Legacy aggregate allocation':'Accepted itemized quote',serviceUsageLabel(entry.occupied_night,entry.details.service_usage),entry.occupied_night?'Yes':'No'];
}
export function ClosedServiceReports({tenant,property,propertyName,timeZone,businessDate,onReviewForward}:{tenant:string;property:string;propertyName:string;timeZone:string;businessDate:string;onReviewForward?:(reservation:string)=>void}){
 const [initialStart]=useState(afterDays(businessDate,-7)),[initialEnd]=useState(afterDays(businessDate,1));const [start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[data,setData]=useState<ClosedServiceReport|null>(null),[loadedKey,setLoadedKey]=useState(''),[busy,setBusy]=useState(true),[error,setError]=useState('');const alive=useRef(true),sequence=useRef(0);const key=tenant+'/'+property+'/'+start+'/'+end;
 async function load(){const seq=++sequence.current;setBusy(true);setLoadedKey('');setError('');try{const result=await hotelRpc<ClosedServiceReport>('service_day_report_v2',{p_tenant:tenant,p_property:property,p_start:start,p_end:end});if(alive.current&&seq===sequence.current){setData(result);setLoadedKey(key)}}catch(e){if(alive.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to read closed service days.')}finally{if(alive.current&&seq===sequence.current)setBusy(false)}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<ClosedServiceReport>('service_day_report_v2',{p_tenant:tenant,p_property:property,p_start:initialStart,p_end:initialEnd}).then(result=>{if(alive.current&&seq===sequence.current){setData(result);setLoadedKey(tenant+'/'+property+'/'+initialStart+'/'+initialEnd);setError('')}}).catch(e=>{if(alive.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to read closed service days.')}).finally(()=>{if(alive.current&&seq===sequence.current)setBusy(false)});return()=>{alive.current=false}},[tenant,property,initialStart,initialEnd]);
 const [exportError,setExportError]=useState('');
 function downloadCsv(){setExportError('');try{exportCsv()}catch{setExportError('The report could not be downloaded. Try Export closed report CSV again, or use Print closed report / PDF.')}}
 const fresh=!!data&&loadedKey===key&&!busy&&!error;
 const rows=fresh?data.entries.map(reportEntry):[];const corrections=fresh?data.forward_entries.map(forwardReportRow):[];
 function exportCsv(){if(!fresh||!data)return;const metadata:ReportCell[][]=[['iRatePilot PMS','Closed service-day allocations'],['Property',propertyName],['Time zone',data.time_zone??timeZone],['From',data.start],['Until (exclusive)',data.end],['Generated at',data.generated_at],['Basis','Original nightly entries plus signed corrections posted within the selected service dates. Pending approvals are excluded. Revenue excludes taxes and OTA fees. This is not payment settlement or a general ledger.'],['Uncategorized amounts','Aggregate approvals and older quotes may not identify named tax/fee categories. Uncategorized amounts preserve the difference.'],['Named fee scope','Named fee columns cover original nightly allocations only. Aggregate forward corrections do not identify Resort, Technology or Cleaning categories.'],['Closed days in period',data.days.length],['First service day',data.first_service_date],['Next unclosed service day',data.next_service_date],['Post-close changes requiring reconciliation',data.reconciliation_pending.length],['Period measure','Original USD','Signed corrections USD','Combined USD'],...[...serviceComponents,['revenue_minor','Revenue subtotal'],['total_minor','Total allocation']].map(([key,label])=>[label,reportMoney(data.ordinary_totals[key as keyof typeof data.ordinary_totals] as number),reportMoney(data.correction_totals[key as keyof typeof data.correction_totals] as number),reportMoney(data.totals[key as keyof typeof data.totals] as number)]),['Occupied nights',data.ordinary_totals.occupied_nights,0,data.totals.occupied_nights],[],['Close register'],['Service date','Close reference','Closed at','Closed by','Original entry count','Correction entry count'],...data.days.map(day=>[day.service_date,day.close_id,day.closed_at,day.closed_by,day.ordinary_entry_count,day.correction_entry_count]),[],headers,...rows,[],['Posted forward corrections in selected service dates'],forwardHeaders,...corrections,[],['Current property approvals awaiting close - all dates, excluded from period totals'],pendingForwardHeaders,...pendingForwardRows(data.pending_adjustments)];downloadReport(propertyName+'-closed-service-days-'+data.start+'-'+data.end,metadata)}
 return <section className="card pilot-reports pilot-closed-reports"><div className="pilot-report-controls"><div className="section-top"><div><h2>Closed nightly revenue, taxes &amp; fees</h2><p>Read the preserved allocations and close register.</p></div><div className="pilot-actions"><button className="secondary" disabled={!fresh} onClick={downloadCsv}>Export closed report CSV</button><button className="secondary" disabled={!fresh} onClick={()=>window.print()}>Print closed report / PDF</button></div></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void load()}}><label className="field">Service date from<input type="date" required value={start} disabled={busy} onChange={e=>setStart(e.target.value)}/></label><label className="field">Service date until (exclusive)<input type="date" required value={end} disabled={busy} onChange={e=>setEnd(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Loading…':'Load closed reports'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}{exportError&&<p className="pilot-error" role="alert">{exportError}</p>}</div>{!fresh?<output className="pilot-empty">{busy?'Loading closed service days…':'Load the selected service dates to view or export the report.'}</output>:data&&<div className="pilot-report-print"><div className="pilot-report-heading"><span className="pilot-eyebrow">{propertyName}</span><h2>Closed service-day allocations</h2><p>{data.start} through {data.end} (end exclusive) · {data.time_zone??timeZone}</p><small>Generated {new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:data.time_zone??timeZone}).format(new Date(data.generated_at))}</small></div><p className="pilot-report-basis">Period totals include original entries and posted corrections on the selected service dates. Original nights remain unchanged. Corrections are separate and add no occupied nights. Revenue excludes taxes and OTA fees. Aggregate approvals and older quotes may not identify named tax/fee categories; those amounts appear as uncategorized. Named fee columns cover original allocations only; aggregate forward corrections do not identify Resort, Technology or Cleaning categories. This report does not represent payment settlement or a general ledger.</p>{!data.initialized&&<p>The service ledger has not started.</p>}{data.reconciliation_pending.length>0&&<div className="pilot-error" role="alert">{data.reconciliation_pending.length} reservations changed after closing and need reconciliation. The closed amounts below remain unchanged.</div>}<p>{data.days.length} closed days in this period · First service day: {data.first_service_date??'Not started'} · Next unclosed day: {data.next_service_date??'Not started'}</p><ServiceTotalsBreakdown ordinary={data.ordinary_totals} corrections={data.correction_totals} total={data.totals}/>{data.reconciliation_pending.length>0&&<section><h3>Review changed charges</h3>{data.reconciliation_pending.map(r=><div className="pilot-list-row" key={r.reservation_id}><span>{r.reservation_id}<small>Changed {r.changed_at}</small></span>{onReviewForward&&<button className="text-button" onClick={()=>onReviewForward(r.reservation_id)}>Review forward correction</button>}</div>)}</section>}<div className="pilot-table-wrap"><table className="pilot-table"><caption>Close register</caption><thead><tr><th scope="col">Service date</th><th scope="col">Close reference</th><th scope="col">Closed at</th><th scope="col">Original rows</th><th scope="col">Correction rows</th></tr></thead><tbody>{data.days.map(day=><tr key={day.close_id}><td>{day.service_date}</td><td>{day.close_id}</td><td>{day.closed_at}</td><td>{day.ordinary_entry_count}</td><td>{day.correction_entry_count}</td></tr>)}</tbody></table></div><div className="pilot-table-wrap"><table className="pilot-table"><caption>Nightly allocations in USD</caption><thead><tr>{headers.map(header=><th scope="col" key={header}>{header}</th>)}{onReviewForward&&<th scope="col">Review</th>}</tr></thead><tbody>{rows.map((row,i)=><tr key={data.entries[i].service_date+'/'+data.entries[i].reservation_id}>{row.map((value,j)=><td key={j}>{value==null?'—':String(value)}</td>)}{onReviewForward&&<td><button className="text-button" onClick={()=>onReviewForward(data.entries[i].reservation_id)}>Review correction</button></td>}</tr>)}</tbody></table>{!rows.length&&<p className="pilot-empty">No allocated stay rows in the selected closed days.</p>}</div><div className="pilot-table-wrap"><table className="pilot-table"><caption>Posted forward corrections in USD</caption><thead><tr>{forwardHeaders.map(h=><th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{corrections.map((row,i)=><tr key={data.forward_entries[i].adjustment_id}>{row.map((v,j)=><td key={j}>{String(v??'—')}</td>)}</tr>)}</tbody></table>{!corrections.length&&<p className="pilot-empty">No posted corrections in the selected service dates.</p>}</div><PendingForwardList entries={data.pending_adjustments} period/><output className="pilot-report-footnote">Preserved report · {rows.length} original nightly allocations · {corrections.length} posted corrections · {data.days.length} closed days.</output></div>}</section>;
}
